    public void initValue()
    {
        FormDataSource formDs = this;
        RetailPeriodicDiscount retailPeriodicDiscount = formDs.cursor();

        next initValue();

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
            retailPeriodicDiscount is GUPMarginComponentPriceAdjustment)
        {
            retailPeriodicDiscount.ConcurrencyMode = RetailDiscountConcurrency::Compounded;
            GUPMarginComponentPriceAdjustment retailPeriodicDiscount_GUPMarginComponentPriceAdjustment = retailPeriodicDiscount as GUPMarginComponentPriceAdjustment;
            retailPeriodicDiscount_GUPMarginComponentPriceAdjustment.PriceComponent = GUPPriceComponent::PriceMarginComponentAdjustment;
        }
    }
